import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double of the pricing downstream (unit price in euros).
const prices = { A: 10, B: 33.5, C: 101, D: 100, E: 0.1, F: 50 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const total = async (items) => (await (await post({ items })).json()).total

test('POST /orders 201 with id, items, total; ids increment', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /application\/json/)
  const o = await res.json()
  assert.deepEqual(o, { id: o.id, items: [{ sku: 'A', qty: 2 }], total: 20 })
  const o2 = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(o2.id), Number(o.id) + 1)
})

test('no discount at or below 100', async () => {
  assert.equal(await total([{ sku: 'D', qty: 1 }]), 100)
  assert.equal(await total([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount above 100', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — 100 pays 100 but 101 pays 90 (cliff: discount applies to the whole order, strictly > 100)
  assert.equal(await total([{ sku: 'C', qty: 1 }]), 90)
  assert.equal(await total([{ sku: 'F', qty: 4 }]), 180)
  assert.equal(await total([{ sku: 'A', qty: 11 }]), 99)
})

test('total is floored to whole euros after discount', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — Math.floor drops cents (and a fractional total is never rounded)
  assert.equal(await total([{ sku: 'B', qty: 3 }]), 90) // 100.5 -> 90.45 -> 90
  assert.equal(await total([{ sku: 'B', qty: 1 }]), 33) // 33.5 -> 33, no discount
  assert.equal(await total([{ sku: 'E', qty: 1 }]), 0) // 0.1 -> 0
  assert.equal(await total([{ sku: 'C', qty: 1 }, { sku: 'A', qty: 1 }]), 99) // 111 -> 99.9 -> 99
})

test('large orders', async () => {
  assert.equal(await total([{ sku: 'C', qty: 10 }]), 909) // 1010 -> 909
  assert.equal(await total([{ sku: 'F', qty: 1000 }]), 45000)
})

test('qty is not validated', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — negative qty gives a negative total; missing qty gives null (NaN)
  assert.equal(await total([{ sku: 'A', qty: -3 }]), -30)
  assert.equal(await total([{ sku: 'A' }]), null)
})

test('unknown sku (pricing returns undefined) yields null total, still 201', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN serialises as null
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('POST /orders 400 for missing, empty, non-array items or invalid JSON', async () => {
  for (const res of [await post({}), await post({ items: [] }), await post({ items: 'x' }), await post(null, '{bad')]) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id returns the stored order', async () => {
  const o = await (await post({ items: [{ sku: 'C', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${o.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), o)
})

test('GET unknown order', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const res = await fetch(`${base}/orders/nope`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('other routes 404', async () => {
  for (const [m, p] of [['GET', '/'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['GET', '/orders/1/x']]) {
    const res = await fetch(base + p, { method: m })
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
